    # Every transaction must balance, and its header must describe exactly the
    # entries it has. Checked at COMMIT, so entries can be inserted in any order.
    op.execute(
        """
        CREATE FUNCTION check_ledger_transaction_balanced() RETURNS TRIGGER AS $$
        DECLARE
            tx_id uuid;
            h_count integer;
            h_total numeric;
            d numeric;
            c numeric;
            n integer;
        BEGIN
            IF TG_TABLE_NAME = 'ledger_transactions' THEN
                tx_id := NEW.id;
            ELSE
                tx_id := NEW.transaction_id;
            END IF;
            SELECT entry_count, total_amount INTO h_count, h_total
              FROM ledger_transactions WHERE id = tx_id;
            SELECT COALESCE(SUM(amount) FILTER (WHERE direction = 'DEBIT'), 0),
                   COALESCE(SUM(amount) FILTER (WHERE direction = 'CREDIT'), 0),
                   COUNT(*)
              INTO d, c, n
              FROM ledger_entries WHERE transaction_id = tx_id;
            IF d <> c THEN
                RAISE EXCEPTION 'Ledger transaction is unbalanced: debits do not equal credits';
            END IF;
            IF n <> h_count OR d <> h_total THEN
                RAISE EXCEPTION 'Ledger transaction entries do not match its header';
            END IF;
            RETURN NULL;
        END;
        $$ LANGUAGE plpgsql;
        """
    )
    for table in ("ledger_transactions", "ledger_entries"):
        op.execute(
            f"""
            CREATE CONSTRAINT TRIGGER trg_{table}_balanced
            AFTER INSERT ON {table}
            DEFERRABLE INITIALLY DEFERRED
            FOR EACH ROW EXECUTE FUNCTION check_ledger_transaction_balanced();
            """
        )

